// ---------------------------------------------------------------------------
// Value builders
// ---------------------------------------------------------------------------

fn nan() -> f64 {
    f64::from_bits(CANONICAL_NAN_BITS)
}

fn ax(length: i32, body: AxisBody) -> CanonicalAxis {
    CanonicalAxis {
        length,
        properties: AxisProperties::default(),
        body,
    }
}

fn int_param(start: i64, step: i64, len: i32) -> CanonicalAxis {
    ax(len, AxisBody::IntegerParametric { start, step })
}

fn int_mat(coords: &[i64]) -> CanonicalAxis {
    ax(
        coords.len() as i32,
        AxisBody::IntegerMaterialized {
            coords: coords.to_vec(),
        },
    )
}

fn float_param(start: f64, step: f64, len: i32) -> CanonicalAxis {
    ax(len, AxisBody::FloatParametric { start, step })
}

fn float_mat(coords: &[f64]) -> CanonicalAxis {
    ax(
        coords.len() as i32,
        AxisBody::FloatMaterialized {
            coords: coords.to_vec(),
        },
    )
}

fn dt_param(start_ts: i64, months: i32, micros: i64, len: i32) -> CanonicalAxis {
    ax(
        len,
        AxisBody::DatetimeParametric {
            start_ts,
            step: Duration { months, micros },
        },
    )
}

fn dt_mat(coords: &[i64]) -> CanonicalAxis {
    ax(
        coords.len() as i32,
        AxisBody::DatetimeMaterialized {
            coords: coords.to_vec(),
        },
    )
}

fn label(labels: &[&str]) -> CanonicalAxis {
    ax(
        labels.len() as i32,
        AxisBody::Label {
            positions: labels
                .iter()
                .enumerate()
                .map(|(i, l)| LabelPos {
                    ordinal: i as i32,
                    label: (*l).to_string(),
                })
                .collect(),
        },
    )
}

fn period(rows: &[(i64, i64, Option<f64>)]) -> CanonicalAxis {
    ax(
        rows.len() as i32,
        AxisBody::Period {
            positions: rows
                .iter()
                .map(|&(start_ts, end_ts, years_presented)| PeriodPos {
                    start_ts,
                    end_ts,
                    years_presented,
                })
                .collect(),
        },
    )
}

fn term(unit: &str, a: i16, b: i16) -> TimePatternTerm {
    TimePatternTerm {
        unit: unit.to_string(),
        range_start: a,
        range_end: b,
    }
}

fn time_pattern(positions: Vec<Vec<TimePatternTerm>>) -> CanonicalAxis {
    ax(
        positions.len() as i32,
        AxisBody::TimePattern {
            positions: positions
                .into_iter()
                .enumerate()
                .map(|(i, terms)| TimePatternPos {
                    ordinal: i as i32,
                    terms,
                })
                .collect(),
        },
    )
}

fn scalar(v: ScalarValue) -> CanonicalValue {
    CanonicalValue {
        tier: Tier::Scalar,
        value_kind: v.kind(),
        axes: vec![],
        shape: ShapedData::Scalar(v),
    }
}

fn array(axes: Vec<CanonicalAxis>, vals: Vec<f64>) -> CanonicalValue {
    CanonicalValue {
        tier: Tier::Array,
        value_kind: ValueKind::Float,
        axes,
        shape: ShapedData::Array(vals),
    }
}

/// A long value; `cells` must be in canonical row-major order.
fn long(axes: Vec<CanonicalAxis>, cells: Vec<(Vec<i32>, ScalarValue)>) -> CanonicalValue {
    let kind = cells[0].1.kind();
    CanonicalValue {
        tier: Tier::Long,
        value_kind: kind,
        axes,
        shape: ShapedData::Long(
            cells
                .into_iter()
                .map(|(positions, value)| LongRow { positions, value })
                .collect(),
        ),
    }
}

/// Rank-1 long float cells at `positions` on an integer-parametric axis.
fn long_f(len: i32, positions: &[i32], base: f64) -> CanonicalValue {
    long(
        vec![int_param(0, 1, len)],
        positions
            .iter()
            .map(|&p| (vec![p], ScalarValue::Float(base + p as f64 * 0.5)))
            .collect(),
    )
}

fn arr_f(vals: &[f64]) -> CanonicalValue {
    array(vec![int_param(0, 1, vals.len() as i32)], vals.to_vec())
}

fn key(e: i64) -> ValueKey {
    ValueKey {
        entity_id: e,
        parameter_definition_id: 1000 + e % 7,
        alternative_id: 1000 + e % 3,
    }
}

const FORCE: WriteOptions = WriteOptions {
    force_replace: true,
    retain_override: None,
};

/// One commit of direct `write_value` / `delete_value` steps.
enum Step {
    W(i64, CanonicalValue),
    Wf(i64, CanonicalValue),
    D(i64),
}

fn run_commit(db: &Path, msg: &str, steps: Vec<Step>, log: &mut String) {
    let outcomes = with_write_txn(db, "golden", msg, |conn, c| {
        let mut cache = AxisCache::new();
        let mut out = Vec::new();
        for s in &steps {
            let o = match s {
                Step::W(e, v) => write_value(
                    conn,
                    c,
                    key(*e),
                    v,
                    &mut cache,
                    &WriteOptions::default(),
                    Some(*e % 5),
                )?,
                Step::Wf(e, v) => write_value(conn, c, key(*e), v, &mut cache, &FORCE, None)?,
                Step::D(e) => delete_value(conn, c, key(*e), &WriteOptions::default())?,
            };
            out.push(o);
        }
        Ok(out)
    })
    .unwrap_or_else(|e| panic!("commit {msg}: {e}"));
    writeln!(log, "## outcomes {msg}").unwrap();
    for o in outcomes {
        writeln!(log, "{o:?}").unwrap();
    }
}

// Entity numbers of the direct-write keys (all >= 1000, disjoint from the
// API-created ids).
const S0: i64 = 1000; // 8 scalar kinds: 1000..1008
const L_FLOAT: i64 = 1010;
const L_INT: i64 = 1011;
const L_BOOL: i64 = 1012;
const L_STR: i64 = 1013;
const L_DT: i64 = 1014;
const L_DUR: i64 = 1015;
const L_R2: i64 = 1016;
const L_R3: i64 = 1017;
const L_R4: i64 = 1018;
const L_1025: i64 = 1019;
const A_1: i64 = 1020;
const A_8760: i64 = 1021;
const A_R2: i64 = 1022;
const A_PER: i64 = 1023;
const T1: i64 = 1030;
const T2: i64 = 1031;
const T3: i64 = 1032;
const RS: i64 = 1040;
const RL: i64 = 1041;
const RA: i64 = 1042;
const FS: i64 = 1043;
const FL: i64 = 1044;
const FA: i64 = 1045;
const DA: i64 = 1050;
const DL: i64 = 1051;
const DS: i64 = 1052;

const H: i64 = 3_600_000_000; // one hour in µs
const Y2020: i64 = 1_577_836_800_000_000; // 2020-01-01T00:00:00Z

fn the_8760() -> Vec<f64> {
    (0..8760)
        .map(|i| {
            if i % 997 == 13 {
                nan()
            } else {
                ((i * 37) % 1000) as f64 * 0.125 - 40.0
            }
        })
        .collect()
}

fn direct_script(db: &Path, log: &mut String) {
    use ScalarValue as S;
    let tricky = "it's \"quoted\" ÄÖ ñ \u{1F680} '' \\ end";
    let scalars = [
        S::Float(1.5),
        S::Float(nan()),
        S::Int(-7),
        S::Bool(true),
        S::Str(tricky.to_string()),
        S::DateTime(TS_MIN_US),
        S::DateTime(TS_MAX_US),
        S::Duration {
            months: 3,
            micros: -5,
        },
    ];
    let mut c1: Vec<Step> = scalars
        .iter()
        .enumerate()
        .map(|(i, v)| Step::W(S0 + i as i64, scalar(v.clone())))
        .collect();

    // Long, every measure kind, rank 1, sparse and on every materialized kind.
    c1.push(Step::W(
        L_FLOAT,
        long(
            vec![int_param(0, 1, 10)],
            vec![
                (vec![0], S::Float(-1.25)),
                (vec![3], S::Float(nan())),
                (vec![7], S::Float(f64::INFINITY)),
                (vec![9], S::Float(f64::MIN_POSITIVE / 4.0)),
            ],
        ),
    ));
    c1.push(Step::W(
        L_INT,
        long(
            vec![int_mat(&[-5, 2, 1000])],
            vec![
                (vec![0], S::Int(i64::MIN)),
                (vec![1], S::Int(0)),
                (vec![2], S::Int(i64::MAX)),
            ],
        ),
    ));
    c1.push(Step::W(
        L_BOOL,
        long(
            vec![label(&["a", "b", "c"])],
            vec![(vec![0], S::Bool(false)), (vec![2], S::Bool(true))],
        ),
    ));
    c1.push(Step::W(
        L_STR,
        long(
            vec![float_mat(&[-1.5, 0.0, 2.25, 1e300])],
            vec![
                (vec![0], S::Str(tricky.to_string())),
                (vec![1], S::Str(String::new())),
                (vec![2], S::Str("''".to_string())),
                (vec![3], S::Str("plain".to_string())),
            ],
        ),
    ));
    c1.push(Step::W(
        L_DT,
        long(
            vec![dt_mat(&[TS_MIN_US, -1, 0, TS_MAX_US])],
            vec![
                (vec![0], S::DateTime(TS_MAX_US)),
                (vec![1], S::DateTime(-1)),
                (vec![2], S::DateTime(0)),
                (vec![3], S::DateTime(TS_MIN_US)),
            ],
        ),
    ));
    c1.push(Step::W(
        L_DUR,
        long(
            vec![dt_param(Y2020, 1, 0, 4)],
            vec![
                (
                    vec![0],
                    S::Duration {
                        months: 0,
                        micros: H,
                    },
                ),
                (
                    vec![2],
                    S::Duration {
                        months: -12,
                        micros: 0,
                    },
                ),
                (
                    vec![3],
                    S::Duration {
                        months: i32::MAX,
                        micros: i64::MIN,
                    },
                ),
            ],
        ),
    ));
    // Rank 2 dense: hourly datetime parametric x label.
    let mut cells = Vec::new();
    for t in 0..3 {
        for l in 0..2 {
            cells.push((vec![t, l], S::Float((t * 10 + l) as f64)));
        }
    }
    c1.push(Step::W(
        L_R2,
        long(vec![dt_param(Y2020, 0, H, 3), label(&["x", "y"])], cells),
    ));
    // Rank 3 sparse: integer materialized x float parametric x label. (A
    // period axis rides an array below: canon never emits a long period
    // dimension, and the golden was generated before the long tier's period
    // accelerator was set to the period start.)
    c1.push(Step::W(
        L_R3,
        long(
            vec![
                int_mat(&[1, 4, 9]),
                float_param(0.5, 0.25, 3),
                label(&["k1", "k2"]),
            ],
            vec![
                (vec![0, 0, 1], S::Int(1)),
                (vec![1, 2, 0], S::Int(2)),
                (vec![2, 1, 1], S::Int(3)),
            ],
        ),
    ));
    // Rank 4 dense: time_pattern x label x integer parametric x datetime
    // materialized (store-range edges in i4_dt).
    let mut cells = Vec::new();
    for a in 0..2 {
        for b in 0..2 {
            for c in 0..2 {
                for d in 0..2 {
                    cells.push((
                        vec![a, b, c, d],
                        S::Float((a * 1000 + b * 100 + c * 10 + d) as f64 / 3.0),
                    ));
                }
            }
        }
    }
    c1.push(Step::W(
        L_R4,
        long(
            vec![
                time_pattern(vec![
                    vec![term("M", 1, 6)],
                    vec![term("h", 1, 8), term("WD", 6, 7)],
                ]),
                label(&["p", "q"]),
                int_param(-3, 3, 2),
                dt_mat(&[TS_MIN_US, TS_MAX_US]),
            ],
            cells,
        ),
    ));
    // 1 025 cells: crosses the old 512-row chunk twice.
    c1.push(Step::W(
        L_1025,
        long_f(1025, &(0..1025).collect::<Vec<_>>(), -100.0),
    ));
    // Arrays: length 1, 8 760 with canonical NaN, and rank 2.
    c1.push(Step::W(A_1, arr_f(&[3.0])));
    c1.push(Step::W(
        A_8760,
        array(vec![dt_param(Y2020, 0, H, 8760)], the_8760()),
    ));
    c1.push(Step::W(
        A_R2,
        array(
            vec![int_param(0, 1, 2), label(&["u", "v", "w"])],
            vec![1.0, 2.0, nan(), 4.0, f64::NEG_INFINITY, 6.0],
        ),
    ));
    c1.push(Step::W(
        A_PER,
        array(
            vec![period(&[
                (Y2020, Y2020 + 8760 * H, Some(2020.0)),
                (Y2020 + 8760 * H, Y2020 + 2 * 8760 * H, None),
            ])],
            vec![0.25, -0.5],
        ),
    ));
    // Transition, replace and delete subjects.
    c1.push(Step::W(T1, arr_f(&[1.0, 2.0, 3.0])));
    c1.push(Step::W(T2, scalar(S::Int(2))));
    c1.push(Step::W(T3, long_f(6, &[0, 2, 4], 1.0)));
    c1.push(Step::W(RS, scalar(S::Str("before".into()))));
    c1.push(Step::W(RL, long_f(9, &[0, 1, 2, 3, 4, 5], 0.0)));
    c1.push(Step::W(RA, arr_f(&[1.0, 2.0])));
    c1.push(Step::W(FS, scalar(S::Float(9.0))));
    c1.push(Step::W(FL, long_f(4, &[0, 1, 3], 2.0)));
    c1.push(Step::W(FA, arr_f(&[7.0, 8.0, 9.0])));
    c1.push(Step::W(DA, arr_f(&[5.0, 6.0])));
    c1.push(Step::W(DL, long_f(5, &[1, 3], 3.0)));
    c1.push(Step::W(DS, scalar(S::Bool(false))));
    run_commit(db, "c1 fresh", c1, log);

    // c2: retained replaces, force replaces (stubs), first transitions, deletes.
    run_commit(
        db,
        "c2 replace",
        vec![
            Step::W(RS, scalar(S::Str("after".into()))),
            Step::W(RL, long_f(9, &[3, 4, 5, 6, 7, 8], 10.0)),
            Step::W(RA, arr_f(&[2.0, 3.0, 4.0])),
            Step::Wf(FS, scalar(S::Float(10.0))),
            Step::Wf(FL, long_f(4, &[1, 2], 20.0)),
            Step::Wf(FA, arr_f(&[nan(), 1.0])),
            Step::W(T1, long_f(3, &[0, 2], 5.0)),
            Step::W(T2, long_f(3, &[1], 6.0)),
            Step::W(T3, arr_f(&[0.0, 1.0])),
            Step::D(DA),
            Step::D(DL),
            Step::D(DS),
        ],
        log,
    );
    // c3: second transitions, re-insert after delete (new array_id), replace again.
    run_commit(
        db,
        "c3 transitions",
        vec![
            Step::W(T1, scalar(S::Float(1.0))),
            Step::W(T2, arr_f(&[4.0, 5.0, 6.0])),
            Step::W(T3, scalar(S::Str("t3".into()))),
            Step::W(DA, arr_f(&[5.0, 6.0, 7.0])),
            Step::W(DL, long_f(5, &[1, 2, 3], 4.0)),
            Step::W(DS, scalar(S::Bool(true))),
            Step::W(RA, arr_f(&[2.0, 3.0, 4.0, 5.0])),
            Step::Wf(RL, long_f(9, &[0, 8], 30.0)),
        ],
        log,
    );
    // c4: close the transition cycles (array -> long -> scalar -> array etc.).
    run_commit(
        db,
        "c4 transitions",
        vec![
            Step::W(T1, arr_f(&[9.0])),
            Step::W(T2, scalar(S::Float(2.0))),
            Step::W(T3, long_f(6, &[5], 7.0)),
            Step::Wf(DA, arr_f(&[1.0])),
        ],
        log,
    );
}

// --- API (segment path) ------------------------------------------------------

fn batch(entity: &[&str], dims: &[(&str, Vec<i64>)], vals: ArrayRef) -> RecordBatch {
    let mut fields = vec![Field::new("entity", DataType::Utf8, false)];
    let mut cols: Vec<ArrayRef> = vec![Arc::new(StringArray::from(entity.to_vec()))];
    for (name, coords) in dims {
        fields.push(Field::new(*name, DataType::Int64, false));
        cols.push(Arc::new(Int64Array::from(coords.clone())));
    }
    fields.push(Field::new("value", vals.data_type().clone(), false));
    cols.push(vals);
    RecordBatch::try_new(Arc::new(Schema::new(fields)), cols).unwrap()
}

fn seg(parameter: &str, alternative: &str, b: RecordBatch) -> Segment {
    Segment {
        class: "node".into(),
        parameter: parameter.into(),
        alternative: alternative.into(),
        batches: vec![b],
        domains: vec![],
    }
}

fn dk(parameter: &str, alternative: &str, entity: &str) -> DeleteKey {
    DeleteKey {
        class: "node".into(),
        parameter: parameter.into(),
        alternative: alternative.into(),
        entity: entity.into(),
    }
}

fn f64s(v: &[f64]) -> ArrayRef {
    Arc::new(Float64Array::from(v.to_vec()))
}

fn i64s(v: &[i64]) -> ArrayRef {
    Arc::new(Int64Array::from(v.to_vec()))
}

fn strs(v: &[&str]) -> ArrayRef {
    Arc::new(StringArray::from(v.to_vec()))
}

fn bools(v: &[bool]) -> ArrayRef {
    Arc::new(BooleanArray::from(v.to_vec()))
}

fn tss(v: &[i64]) -> ArrayRef {
    Arc::new(TimestampMicrosecondArray::from(v.to_vec()))
}

fn oalt(name: &str, cascade: bool) -> (ObjectDeleteKey, ObjectDeleteOpts) {
    (
        ObjectDeleteKey {
            kind: ObjectKind::Alternative,
            class: None,
            target: ObjectRef::Name(name.into()),
        },
        ObjectDeleteOpts { cascade },
    )
}

fn api_script(db: &Path, log: &mut String) {
    let o = WriteOptions::default();
    // a1: multi-segment fresh writes (array with -0.0, which canon
    // normalizes; scalars; a sparse int long; a 600-cell long; a second
    // alternative for the object delete below).
    let r = commit_changes(
        db,
        vec![
            seg(
                "profile",
                "Base",
                batch(
                    &["n1"; 4],
                    &[("t", vec![0, 1, 2, 3])],
                    f64s(&[-0.0, 1.0, 2.0, 3.0]),
                ),
            ),
            seg(
                "demand",
                "Base",
                batch(&["n1", "n2"], &[], f64s(&[4.5, -0.0])),
            ),
            seg(
                "flow",
                "Base",
                batch(&["n1"; 3], &[("t", vec![0, 2, 5])], i64s(&[1, 2, 3])),
            ),
            seg(
                "big",
                "Base",
                batch(
                    &["n3"; 600],
                    &[("t", (0..600).map(|i| i * 3 + (i % 2)).collect())],
                    i64s(&(0..600).collect::<Vec<_>>()),
                ),
            ),
            seg("demand", "altV", batch(&["n1"], &[], f64s(&[8.0]))),
        ],
        vec![],
        vec![],
        vec![],
        "golden",
        "a1 segments",
        o,
    )
    .expect("a1");
    writeln!(log, "## report a1\n{r:?}").unwrap();

    // a2: writes, then deletes of OTHER keys, then an object delete — all in
    // one commit (the read-after-write order of the plan's §4.1).
    let r = commit_changes(
        db,
        vec![
            seg(
                "profile",
                "Base",
                batch(&["n1"; 3], &[("t", vec![0, 1, 2])], f64s(&[9.0, 8.0, 7.0])),
            ),
            seg(
                "big",
                "Base",
                batch(
                    &["n3"; 300],
                    &[("t", (0..300).map(|i| i * 5).collect())],
                    i64s(&(0..300).map(|i| -i).collect::<Vec<_>>()),
                ),
            ),
            seg(
                "flow",
                "altV",
                batch(&["n1"; 2], &[("t", vec![1, 4])], i64s(&[10, 20])),
            ),
        ],
        vec![],
        vec![
            dk("demand", "Base", "n2"),
            dk("flow", "Base", "n1"),
            dk("demand", "Base", "nobody"),
        ],
        vec![oalt("altV", false)],
        "golden",
        "a2 writes+deletes",
        o,
    )
    .expect("a2");
    writeln!(log, "## report a2\n{r:?}").unwrap();

    // a3: cascade-delete the alternative: closes rows written by a1 and a2.
    let r = commit_changes(
        db,
        vec![],
        vec![],
        vec![],
        vec![oalt("altV", true)],
        "golden",
        "a3 object delete",
        o,
    )
    .expect("a3");
    writeln!(log, "## report a3\n{r:?}").unwrap();

    api_scalar_batches(db, log);
    api_long_array_delete_batches(db, log);
    direct_empty_arrays(db, log);
}

/// One `commit_changes` call, its report logged under `tag`.
fn api_commit(
    db: &Path,
    tag: &str,
    segments: Vec<Segment>,
    structural: Vec<StructuralChange>,
    deletes: Vec<DeleteKey>,
    opts: WriteOptions,
    log: &mut String,
) {
    let r = commit_changes(
        db,
        segments,
        structural,
        deletes,
        vec![],
        "golden",
        tag,
        opts,
    )
    .unwrap_or_else(|e| panic!("{tag}: {e}"));
    writeln!(log, "## report {tag}\n{r:?}").unwrap();
}

/// API-path scalar batches (set_based_scalar_write_PLAN §5.1, a4-a8):
/// several scalar segments per commit, auto-created entities, replaces with
/// and without retention, tier transitions through the API, writes plus
/// deletes in one commit, every scalar value kind the Arrow contract
/// carries, and the report's first-seen tier order. Generated by the per-key
/// scalar writer; the set-based writer must reproduce it unchanged.
fn api_scalar_batches(db: &Path, log: &mut String) {
    let o = WriteOptions::default();
    // a4: four scalar segments in one commit: a replace of n1 plus new n4,
    // n5 (auto-created), a new parameter over n1 and n4, a string and a bool
    // segment. Then the same keys again under force_replace (stub
    // close-outs).
    api_commit(
        db,
        "a4 scalar batch",
        vec![
            seg(
                "demand",
                "Base",
                batch(&["n1", "n4", "n5"], &[], f64s(&[5.5, 6.0, nan()])),
            ),
            seg(
                "cap",
                "Base",
                batch(&["n1", "n4"], &[], f64s(&[100.0, -0.0])),
            ),
            seg(
                "label",
                "Base",
                batch(&["n1", "n2"], &[], strs(&["x", "it's \"q\" ÄÖ"])),
            ),
            seg("flag", "Base", batch(&["n4"], &[], bools(&[true]))),
        ],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "a4 force replace",
        vec![
            seg(
                "demand",
                "Base",
                batch(&["n1", "n4", "n5"], &[], f64s(&[7.0, 8.0, 9.0])),
            ),
            seg("cap", "Base", batch(&["n1", "n4"], &[], f64s(&[1.0, 2.0]))),
            seg("label", "Base", batch(&["n1"], &[], strs(&["y"]))),
            seg("flag", "Base", batch(&["n4"], &[], bools(&[false]))),
        ],
        vec![],
        vec![],
        WriteOptions {
            force_replace: true,
            retain_override: None,
        },
        log,
    );

    // a5: tier transitions through the API. `mixed` declares a rank-0 float
    // member and a rank-1 member; n1 gets a long value (int measure), n2 an
    // array, then one commit rewrites both as scalars (long -> scalar,
    // array -> scalar) and adds new n6; then n1 goes back to long (scalar ->
    // long, the per-key path).
    let mixed = StructuralChange::CreateParameter {
        class: "node".into(),
        name: "mixed".into(),
        types: vec![
            TypeDecl {
                kind: "float".into(),
                dims: None,
            },
            TypeDecl {
                kind: "indexed".into(),
                dims: Some(vec![DimSpec {
                    name: "t".into(),
                    kind: "integer".into(),
                }]),
            },
        ],
        value_list: None,
        description: None,
    };
    api_commit(
        db,
        "a5 mixed long",
        vec![seg(
            "mixed",
            "Base",
            batch(&["n1"; 2], &[("t", vec![0, 3])], i64s(&[11, 12])),
        )],
        vec![mixed],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "a5 mixed array",
        vec![seg(
            "mixed",
            "Base",
            batch(&["n2"; 3], &[("t", vec![0, 1, 2])], f64s(&[1.0, 2.0, 3.0])),
        )],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "a5 to scalar",
        vec![seg(
            "mixed",
            "Base",
            batch(&["n1", "n2", "n6"], &[], f64s(&[0.5, 0.25, 0.125])),
        )],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "a5 back to long",
        vec![seg(
            "mixed",
            "Base",
            batch(&["n1"; 2], &[("t", vec![1, 4])], i64s(&[21, 22])),
        )],
        vec![],
        vec![],
        o,
        log,
    );

    // a6: a scalar batch in the same commit as a delete of another scalar
    // key and a delete of a long key.
    api_commit(
        db,
        "a6 writes+deletes",
        vec![seg(
            "demand",
            "Base",
            batch(&["n4", "n6"], &[], f64s(&[40.0, 60.0])),
        )],
        vec![],
        vec![dk("cap", "Base", "n1"), dk("big", "Base", "n3")],
        o,
        log,
    );

    // a7: int and date_time scalar segments (the float/string/bool lists are
    // all NULL in this batch; a4 had int/date_time all NULL).
    api_commit(
        db,
        "a7 int+datetime",
        vec![
            seg(
                "count",
                "Base",
                batch(&["n1", "n2", "n4"], &[], i64s(&[i64::MIN, 0, i64::MAX])),
            ),
            seg(
                "when",
                "Base",
                batch(&["n1", "n5"], &[], tss(&[TS_MIN_US, Y2020])),
            ),
        ],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "a7 replace",
        vec![
            seg("count", "Base", batch(&["n1"], &[], i64s(&[1]))),
            seg("when", "Base", batch(&["n5"], &[], tss(&[TS_MAX_US]))),
        ],
        vec![],
        vec![],
        o,
        log,
    );

    // a8: the report's first-seen tier order with a scalar FIRST, then a
    // long and an array segment ([Scalar, Long, Array]).
    api_commit(
        db,
        "a8 tier order",
        vec![
            seg("demand", "Base", batch(&["n7"], &[], f64s(&[70.0]))),
            seg(
                "flow",
                "Base",
                batch(&["n4"; 2], &[("t", vec![0, 9])], i64s(&[3, 4])),
            ),
            seg(
                "profile",
                "Base",
                batch(&["n4"; 2], &[("t", vec![0, 1])], f64s(&[1.0, 2.0])),
            ),
        ],
        vec![],
        vec![],
        o,
        log,
    );
}

/// A rank-2 batch over int dims `t` and `s` with an int measure.
fn grid(entity: &[&str], t: &[i64], s: &[i64], vals: &[i64]) -> RecordBatch {
    batch(entity, &[("t", t.to_vec()), ("s", s.to_vec())], i64s(vals))
}

/// Create a `retain_content = FALSE` definition in class `node` (a result
/// class), stamped with the latest commit. Raw SQL: no API sets it.
fn create_unretained_parameter(db: &Path, name: &str) {
    let conn = Connection::open(db).unwrap();
    conn.execute(
        "INSERT INTO parameter_definition \
           (entity_class_id, name, retain_content, valid_from_commit) \
         SELECT (SELECT id FROM entity_class WHERE cur_name = 'node'), ?, FALSE, \
                (SELECT max(id) FROM \"commit\")",
        [name],
    )
    .unwrap();
    conn.close().unwrap();
}

/// API-path long, array and delete batches (set_based_long_and_delete_PLAN
/// §5.1 as amended by critique C8, b1-b7): multi-key long segments over
/// diverged per-cell versions and retention stubs, a sparse rank-2 long, a
/// `retain_content = FALSE` long parameter, tier transitions in every
/// direction through the API, cross-segment commits, multi-key array rounds
/// (`array_id` minting, `_hist` rows, NaN and -0.0), one delete commit over
/// every tier and every warning, and writes plus deletes in one commit.
/// Generated by the per-key long, array and delete writers; the set-based
/// writers must reproduce it unchanged.
fn api_long_array_delete_batches(db: &Path, log: &mut String) {
    let o = WriteOptions::default();
    // b1 prep: diverge the per-cell versions of lp/n1 and lp/n2. n1: two
    // cells (pos0 v1, pos1 v1), one cell under force_replace (pos0 v2, pos1
    // closed as a stub), three cells (pos0 v3, pos1 v2, pos2 v1). n2: three
    // cells, then one cell under force_replace (pos1, pos2 closed as stubs).
    api_commit(
        db,
        "b1 prep v1",
        vec![seg(
            "lp",
            "Base",
            batch(
                &["n1", "n1", "n2", "n2", "n2"],
                &[("t", vec![0, 1, 0, 1, 2])],
                i64s(&[1, 2, 3, 4, 5]),
            ),
        )],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "b1 prep v2 force",
        vec![seg(
            "lp",
            "Base",
            batch(&["n1", "n2"], &[("t", vec![1, 1])], i64s(&[6, 7])),
        )],
        vec![],
        vec![],
        FORCE,
        log,
    );
    api_commit(
        db,
        "b1 prep v3",
        vec![seg(
            "lp",
            "Base",
            batch(&["n1"; 3], &[("t", vec![0, 1, 2])], i64s(&[8, 9, 10])),
        )],
        vec![],
        vec![],
        o,
        log,
    );
    // b1: one multi-key long segment: n1 two cells (pos0 v4, pos1 v3, pos2
    // stays dead at v1), n2 three cells over its stubs, n8 a new entity
    // (minted) and n5 an existing entity without an lp value. A sparse
    // rank-2 segment whose two axes are equal (1 created + 1 reused).
    api_commit(
        db,
        "b1 long batch",
        vec![
            seg(
                "lp",
                "Base",
                batch(
                    &["n1", "n1", "n2", "n2", "n2", "n8", "n8", "n5"],
                    &[("t", vec![3, 4, 0, 1, 2, 0, 1, 7])],
                    i64s(&[11, 12, 13, 14, 15, 16, 17, 18]),
                ),
            ),
            seg(
                "grid",
                "Base",
                grid(&["n1", "n1", "n2"], &[0, 1, 0], &[0, 1, 1], &[1, 2, 3]),
            ),
        ],
        vec![],
        vec![],
        o,
        log,
    );

    // b2: the same parameters under force_replace (stub close-outs; grid/n1
    // moves to other positions, so (0,0) stays dead); then a
    // retain_content = FALSE long parameter written twice.
    api_commit(
        db,
        "b2 force",
        vec![
            seg(
                "lp",
                "Base",
                batch(
                    &["n1", "n1", "n1", "n2", "n8", "n8"],
                    &[("t", vec![0, 1, 2, 5, 0, 1])],
                    i64s(&[21, 22, 23, 24, 25, 26]),
                ),
            ),
            seg(
                "grid",
                "Base",
                grid(&["n1"; 3], &[0, 1, 1], &[1, 0, 1], &[4, 5, 6]),
            ),
        ],
        vec![],
        vec![],
        FORCE,
        log,
    );
    create_unretained_parameter(db, "lres");
    api_commit(
        db,
        "b2 unretained v1",
        vec![seg(
            "lres",
            "Base",
            batch(
                &["n1", "n1", "n2", "n2"],
                &[("t", vec![0, 1, 0, 1])],
                i64s(&[1, 2, 3, 4]),
            ),
        )],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "b2 unretained v2",
        vec![seg(
            "lres",
            "Base",
            batch(
                &["n1", "n2", "n2", "n2", "n3"],
                &[("t", vec![0, 0, 1, 2, 0])],
                i64s(&[5, 6, 7, 8, 9]),
            ),
        )],
        vec![],
        vec![],
        o,
        log,
    );

    // b3: tier transitions in one commit on `mixed` (rank 0 float or rank 1
    // integer t). Prep: n9 array on Base; n1 long on Alt3; n2 long on Alt4;
    // n4 scalar on Alt3. (After a5: n1 long, n2 and n6 scalar on Base.)
    api_commit(
        db,
        "b3 prep a",
        vec![
            seg(
                "mixed",
                "Base",
                batch(&["n9"; 2], &[("t", vec![0, 1])], f64s(&[1.5, 2.5])),
            ),
            seg(
                "mixed",
                "Alt3",
                batch(&["n1"; 2], &[("t", vec![0, 2])], i64s(&[31, 32])),
            ),
            seg(
                "mixed",
                "Alt4",
                batch(&["n2"; 2], &[("t", vec![1, 2])], i64s(&[41, 42])),
            ),
        ],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "b3 prep b",
        vec![seg("mixed", "Alt3", batch(&["n4"], &[], f64s(&[0.75])))],
        vec![],
        vec![],
        o,
        log,
    );
    // Base: n2 scalar -> long, n9 array -> long, n1 long -> long. Alt3: n1
    // long -> array, n4 scalar -> array, n6 new. Alt4: n2 long -> scalar.
    api_commit(
        db,
        "b3 transitions",
        vec![
            seg(
                "mixed",
                "Base",
                batch(
                    &["n2", "n2", "n9", "n1"],
                    &[("t", vec![0, 1, 1, 4])],
                    i64s(&[51, 52, 53, 54]),
                ),
            ),
            seg(
                "mixed",
                "Alt3",
                batch(
                    &["n1", "n1", "n4", "n4", "n6", "n6"],
                    &[("t", vec![0, 1, 0, 1, 0, 1])],
                    f64s(&[6.0, 6.5, 7.0, 7.5, 8.0, 8.5]),
                ),
            ),
            seg("mixed", "Alt4", batch(&["n2"], &[], f64s(&[9.25]))),
        ],
        vec![],
        vec![],
        o,
        log,
    );

    // b4: cross-segment: a scalar segment first, three long segments x 1
    // key, two array segments x 2 keys (one a new parameter).
    api_commit(
        db,
        "b4 cross-segment",
        vec![
            seg("demand", "Base", batch(&["n7"], &[], f64s(&[71.0]))),
            seg(
                "flow",
                "Base",
                batch(&["n5"; 2], &[("t", vec![2, 3])], i64s(&[5, 6])),
            ),
            seg(
                "lp",
                "Base",
                batch(&["n3"; 2], &[("t", vec![0, 9])], i64s(&[7, 8])),
            ),
            seg(
                "big",
                "Base",
                batch(&["n4"; 3], &[("t", vec![1, 2, 3])], i64s(&[9, 10, 11])),
            ),
            seg(
                "profile",
                "Base",
                batch(
                    &["n2", "n2", "n5", "n5"],
                    &[("t", vec![0, 1, 0, 1])],
                    f64s(&[1.0, 2.0, 3.0, 4.0]),
                ),
            ),
            seg(
                "prof2",
                "Base",
                batch(
                    &["n1", "n1", "n1", "n3", "n3", "n3"],
                    &[("t", vec![0, 1, 2, 0, 1, 2])],
                    f64s(&[0.5, 1.5, 2.5, 3.5, 4.5, 5.5]),
                ),
            ),
        ],
        vec![],
        vec![],
        o,
        log,
    );

    // b5: a multi-key array segment with replaced (n1, n4) and new (n7, n6)
    // keys, carrying a canonical NaN, -0.0 (canon normalizes it) and a
    // one-element array; then a force_replace round (stub `_hist` rows).
    api_commit(
        db,
        "b5 arrays",
        vec![seg(
            "profile",
            "Base",
            batch(
                &["n1", "n1", "n1", "n4", "n7", "n7", "n6", "n6", "n6"],
                &[("t", vec![0, 1, 2, 5, 0, 1, 0, 1, 2])],
                f64s(&[nan(), -0.0, 1.0, 2.5, -0.0, nan(), 3.0, 4.0, 5.0]),
            ),
        )],
        vec![],
        vec![],
        o,
        log,
    );
    api_commit(
        db,
        "b5 arrays force",
        vec![seg(
            "profile",
            "Base",
            batch(
                &["n1", "n2", "n2", "n8"],
                &[("t", vec![0, 0, 1, 0])],
                f64s(&[1.25, nan(), 2.25, -0.0]),
            ),
        )],
        vec![],
        vec![],
        FORCE,
        log,
    );

    // b6: one delete commit over all three tiers. A `retain_content =
    // FALSE` long key (lres), an array, a scalar, a sparse rank-2 long, an
    // array under `mixed`; an UnknownReferent at each of the four levels; a
    // NothingToDelete (cap/n1 was deleted in a6); an exact duplicate
    // (deduped up front); and a final-sigma pair that Rust's fold keeps
    // apart ("ΑΣ" -> "ας") but DuckDB's lower() resolves to one entity
    // ("ασ"): the first deletes, the second gets NothingToDelete.
    api_commit(
        db,
        "b6 prep",
        vec![seg("demand", "Base", batch(&["ασ"], &[], f64s(&[1.0])))],
        vec![],
        vec![],
        o,
        log,
    );
    let unknown_class = DeleteKey {
        class: "no_such_class".into(),
        parameter: "demand".into(),
        alternative: "Base".into(),
        entity: "n1".into(),
    };
    api_commit(
        db,
        "b6 deletes",
        vec![],
        vec![],
        vec![
            dk("lres", "Base", "n1"),
            dk("profile", "Base", "n7"),
            dk("demand", "Base", "n4"),
            dk("no_such_param", "Base", "n1"),
            unknown_class,
            dk("demand", "NoSuchAlt", "n1"),
            dk("demand", "Base", "nobody2"),
            dk("cap", "Base", "n1"),
            dk("lres", "Base", "n1"),
            dk("demand", "Base", "ΑΣ"),
            dk("demand", "Base", "ασ"),
            dk("grid", "Base", "n1"),
            dk("mixed", "Alt3", "n1"),
            dk("lres", "Base", "n2"),
        ],
        o,
        log,
    );

    // b7: long and array writes in the same commit as deletes of other
    // keys of the same parameters.
    api_commit(
        db,
        "b7 writes+deletes",
        vec![
            seg(
                "lp",
                "Base",
                batch(&["n1"; 2], &[("t", vec![0, 2])], i64s(&[61, 62])),
            ),
            seg(
                "profile",
                "Base",
                batch(&["n5"; 2], &[("t", vec![0, 1])], f64s(&[6.5, 7.5])),
            ),
        ],
        vec![],
        vec![
            dk("lp", "Base", "n2"),
            dk("profile", "Base", "n2"),
            dk("flow", "Base", "n5"),
        ],
        o,
        log,
    );
}

/// Direct empty-array writes (critique C8): an empty payload binds as an
/// empty `DOUBLE[]` on insert and on replace, and moves to `_hist` on a
/// delete. Canon never emits one, so only the direct entry point reaches
/// it.
fn direct_empty_arrays(db: &Path, log: &mut String) {
    const E: i64 = 1060;
    run_commit(
        db,
        "c5 empty array",
        vec![Step::W(E, array(vec![int_param(0, 1, 1)], vec![]))],
        log,
    );
    run_commit(
        db,
        "c5 empty array replace",
        vec![Step::W(E, array(vec![int_param(0, 1, 1)], vec![]))],
        log,
    );
    // An empty live array fails `audit_array_integrity` (length 0 against a
    // length-1 axis), so the key is deleted again: its rows stay in `_hist`.
    run_commit(db, "c5 empty array delete", vec![Step::D(E)], log);
}

// ---------------------------------------------------------------------------
// Rendering (in Rust, never DuckDB's ::VARCHAR)
// ---------------------------------------------------------------------------

fn render(v: &Value) -> String {
    match v {
        Value::Null => "NULL".into(),
        Value::Boolean(b) => b.to_string(),
        Value::TinyInt(x) => x.to_string(),
        Value::SmallInt(x) => x.to_string(),
        Value::Int(x) => x.to_string(),
        Value::BigInt(x) => x.to_string(),
        Value::HugeInt(x) => x.to_string(),
        Value::UTinyInt(x) => x.to_string(),
        Value::USmallInt(x) => x.to_string(),
        Value::UInt(x) => x.to_string(),
        Value::UBigInt(x) => x.to_string(),
        Value::Float(x) => format!("f32:{:08x}", x.to_bits()),
        Value::Double(x) => format!("f:{:016x}", x.to_bits()),
        Value::Text(s) => format!("{s:?}"),
        Value::Timestamp(unit, x) => {
            let us = match unit {
                TimeUnit::Second => x * 1_000_000,
                TimeUnit::Millisecond => x * 1_000,
                TimeUnit::Microsecond => *x,
                TimeUnit::Nanosecond => x / 1_000,
            };
            format!("ts:{us}")
        }
        Value::List(items) => {
            let parts: Vec<String> = items.iter().map(render).collect();
            if parts.len() > 64 {
                let mut h: u64 = 0xcbf2_9ce4_8422_2325;
                for p in &parts {
                    for b in p.bytes().chain(std::iter::once(b',')) {
                        h ^= b as u64;
                        h = h.wrapping_mul(0x0100_0000_01b3);
                    }
                }
                format!(
                    "[len={} fnv={h:016x} head={}]",
                    parts.len(),
                    parts[..4].join(",")
                )
            } else {
                format!("[{}]", parts.join(","))
            }
        }
        other => panic!("golden renderer: unhandled value {other:?}"),
    }
}

fn dump_query(conn: &Connection, title: &str, sql: &str, out: &mut String) {
    let mut stmt = conn.prepare(sql).unwrap();
    let mut rows = stmt.query([]).unwrap();
    let names: Vec<String> = rows.as_ref().unwrap().column_names();
    writeln!(out, "## {title} ({})", names.join(",")).unwrap();
    while let Some(row) = rows.next().unwrap() {
        let cells: Vec<String> = (0..names.len())
            .map(|i| render(&row.get::<_, Value>(i).unwrap()))
            .collect();
        writeln!(out, "{}", cells.join("|")).unwrap();
    }
}

fn dump(db: &Path) -> String {
    let conn = Connection::open(db).unwrap();
    let mut out = String::new();
    dump_query(
        &conn,
        "commit",
        "SELECT * EXCLUDE (timestamp) FROM commit ORDER BY id",
        &mut out,
    );
    for t in TABLES {
        dump_query(
            &conn,
            t,
            &format!("SELECT * FROM {t} ORDER BY ALL"),
            &mut out,
        );
    }
    dump_query(
        &conn,
        "sequences",
        "SELECT sequence_name, last_value FROM duckdb_sequences() ORDER BY sequence_name",
        &mut out,
    );
    conn.close().unwrap();
    out
}

fn assert_audits_clean(db: &Path) {
    let conn = Connection::open(db).unwrap();
    for a in AUDITS {
        let n: i64 = conn
            .query_row(&format!("SELECT count(*) FROM {a}"), [], |r| r.get(0))
            .unwrap();
        assert_eq!(n, 0, "{a} must be empty");
    }
    conn.close().unwrap();
}

/// Soft check (plan §7.1): the file size after CHECKPOINT is printed, not
/// asserted (findings §1.2: equal ±1 block across write mechanisms).
fn report_file_size(db: &Path) {
    let conn = Connection::open(db).unwrap();
    conn.execute_batch("CHECKPOINT").unwrap();
    conn.close().unwrap();
    let size = std::fs::metadata(db).unwrap().len();
    println!("write_path_golden: file size after CHECKPOINT = {size} bytes");
}

fn build_golden_db(dir: &Path) -> (PathBuf, String) {
    let db = dir.join("golden.duckdb");
    init_schema_with_default(&db, Some("Base")).expect("init");
    let mut log = String::new();
    direct_script(&db, &mut log);
    api_script(&db, &mut log);
    (db, log)
}

#[test]
fn write_path_golden() {
    let dir = tempfile::tempdir().unwrap();
    let (db, log) = build_golden_db(dir.path());
    assert_audits_clean(&db);
    let got = format!("{log}{}", dump(&db));
    report_file_size(&db);

    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join(FIXTURE);
    if std::env::var("NODAL_REGEN_GOLDEN").as_deref() == Ok("1") {
        std::fs::write(&path, &got).unwrap();
        eprintln!("write_path_golden: regenerated {}", path.display());
        return;
    }
    let want = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e} (generate it with NODAL_REGEN_GOLDEN=1)",
            path.display()
        )
    });
    if got != want {
        let (g, w): (Vec<&str>, Vec<&str>) = (got.lines().collect(), want.lines().collect());
        let first = g
            .iter()
            .zip(&w)
            .position(|(a, b)| a != b)
            .unwrap_or(g.len().min(w.len()));
        panic!(
            "physical-write golden mismatch at line {} (got {} lines, want {}):\n  got:  {}\n  want: {}",
            first + 1,
            g.len(),
            w.len(),
            g.get(first).unwrap_or(&"<eof>"),
            w.get(first).unwrap_or(&"<eof>"),
        );
    }
}
